const SISTEMA = "Você escreve em nome de Eduardo Cardoso, em português do Brasil.\n\nQUEM É O EDUARDO (use só estes fatos, nunca invente outros):\n- Mora em Chapecó/SC. Experiência real em suporte técnico (Help Desk) e em automação de processos com n8n, APIs e LLMs.\n- Faz pós-graduação em IA, com foco em agentes.\n- Projetos reais: Mentor de Gestão Industrial (multiagente com CrewAI, RAG com ChromaDB, Streamlit, demo no Hugging Face); replicador de promoções de Pokémon TCG para WhatsApp (Node.js/TypeScript, rodando 24/7 numa VPS com Coolify e painel próprio); PC Dashboard (app desktop em Tauri/Rust); conversor de unidades (React/TypeScript); este próprio copiloto de LinkedIn em n8n.\n- Busca trabalho remoto em automação/IA, suporte técnico ou suporte a produto de IA. Nunca escreva \"busco vaga\", \"open to work\" ou similar no texto.\n\nVOZ:\n- Pragmático, de colega para colega. Direto, técnico sem ser pedante, honesto sobre erros e limites.\n- Nada de palco, motivacional ou autopromoção vazia.\n\nPROIBIDO:\n- Travessão longo (—) ou meia-risca (–). Use vírgula, ponto ou parênteses.\n- Mais de 1 emoji no texto inteiro. Emojis 🚀🔥💡👏📌👇🎯 nunca.\n- Listas com marcadores transformando o texto em slide. Prefira parágrafos curtos.\n- Aberturas clichê: \"No mundo acelerado...\", \"Você já parou para pensar...\", \"Recentemente me deparei...\", \"No cenário atual...\".\n- Fechamentos pedindo engajamento: \"E você, o que acha? Comenta aí\", \"Compartilhe\", \"Salve este post\".\n- Palavras: disruptivo, mindset, ecossistema, revolucionar, game changer, sinergia, fora da caixa, jornada.\n- Números, clientes, resultados ou experiências que não estejam nos fatos acima ou na ideia enviada.\n";
const P_POST = "Escreva duas versões de post para o LinkedIn a partir da ideia abaixo.\n\nVersão 1 (Bastidores): narrativa curta de algo que aconteceu na prática, a dor real e o que ele aprendeu.\nVersão 2 (Arquitetura): foco técnico, comparando o jeito frágil com o jeito robusto de resolver.\n\nRegras de formato para as duas:\n- 900 a 1.500 caracteres.\n- Primeira linha é um gancho seco, uma afirmação forte ou o problema direto.\n- Parágrafos de 1 a 3 linhas separados por linha em branco (leitura no celular).\n- Termina com uma constatação honesta de engenharia ou uma pergunta natural entre profissionais, sem pedir engajamento.\n- No máximo 3 hashtags no final, relevantes (ex.: #n8n #automacao #IA).\n\nTambém gere um prompt de imagem em inglês técnico para o Meta AI: infográfico ou diagrama em dark mode (#0f172a), 16:9, com todos os textos da imagem em português entre aspas, sem robôs, sem vidro 3D, sem esferas brilhantes, sem textos em inglês.\n\nResponda SOMENTE com JSON válido neste formato:\n{\"v1\": \"texto da versão 1\", \"v2\": \"texto da versão 2\", \"imagem\": \"prompt da imagem\"}\n\nIDEIA:\n";
const P_COMENT = "Abaixo está o texto de um post do LinkedIn de outra pessoa. Escreva dois comentários que o Eduardo poderia publicar nele.\n\nComentário 1: acrescenta um ponto técnico ou prático que o post não disse, ligado à experiência real dele quando fizer sentido.\nComentário 2: faz uma pergunta específica e inteligente sobre o conteúdo, que puxe conversa com o autor.\n\nRegras:\n- 2 a 4 frases cada. Nada de \"Ótimo post!\", \"Parabéns pela reflexão\", \"Concordo totalmente\".\n- Não elogie o autor de forma genérica, não se promova, não peça conexão.\n- Escreva no mesmo idioma do post.\n- Se o post for vago demais para comentar algo útil, diga isso no campo \"aviso\" e ainda assim sugira os comentários.\n\nResponda SOMENTE com JSON válido neste formato:\n{\"c1\": \"comentário 1\", \"c2\": \"comentário 2\", \"aviso\": \"\"}\n\nPOST:\n";
const AJUDA = "Copiloto LinkedIn\n\n/post <ideia>  gera 2 versoes de post (Bastidores e Arquitetura) + prompt de imagem\n/comentar <texto do post>  sugere 2 comentarios\nColar o texto de um post (sem comando) tambem gera comentarios.\n/status  confere se esta tudo de pe\n/menu  mostra esta ajuda\n\nNada e publicado sozinho: voce copia, ajusta e posta.";

const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};

const secret = $env.TG_WEBHOOK_SECRET;
if (secret && headers['x-telegram-bot-api-secret-token'] !== secret) return [];

const msg = body.message || body.edited_message;
if (!msg || !msg.chat) return [];
const chatId = String(msg.chat.id);
if (chatId !== String($env.TELEGRAM_CHAT_ID)) return [];

const text = (msg.text || msg.caption || '').trim();
if (!text) {
  return [{ json: { chatId, needsLlm: false, reply: 'Por enquanto eu so entendo texto. Manda /menu para ver os comandos.' } }];
}

const m = text.match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
const cmd = m ? m[1].toLowerCase() : null;
const arg = m ? m[2].trim() : text;

function llm(kind, userContent) {
  return {
    chatId,
    needsLlm: true,
    kind,
    session: 'copiloto-' + chatId + '-' + kind,
    ack: kind === 'post' ? 'Escrevendo 2 versoes do post...' : 'Lendo o post e pensando nos comentarios...',
    llmBody: {
      model: $env.LLM_MODEL || 'deepseek-v4.1-flash',
      temperature: 0.8,
      max_tokens: 3000,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SISTEMA },
        { role: 'user', content: userContent },
      ],
    },
  };
}

if (cmd === 'start' || cmd === 'menu' || cmd === 'ajuda' || cmd === 'help') {
  return [{ json: { chatId, needsLlm: false, reply: AJUDA } }];
}
if (cmd === 'status') {
  const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  return [{ json: { chatId, needsLlm: false, reply: 'No ar.\nModelo: ' + ($env.LLM_MODEL || '?') + '\nHora do servidor: ' + agora } }];
}
if (cmd === 'post') {
  if (!arg) return [{ json: { chatId, needsLlm: false, reply: 'Manda a ideia junto. Ex.: /post o dia em que meu agente de IA estourou o limite da API e como eu resolvi com fila' } }];
  return [{ json: llm('post', P_POST + arg) }];
}
if (cmd === 'comentar') {
  if (!arg) return [{ json: { chatId, needsLlm: false, reply: 'Cola o texto do post depois do comando, ou so cola o texto direto sem comando.' } }];
  return [{ json: llm('comentario', P_COMENT + arg) }];
}
if (cmd) {
  return [{ json: { chatId, needsLlm: false, reply: 'Comando desconhecido. /menu mostra o que eu sei fazer.' } }];
}
if (/linkedin\.com|lnkd\.in/i.test(text) && text.length < 300) {
  return [{ json: { chatId, needsLlm: false, reply: 'Eu nao abro links do LinkedIn (para proteger sua conta). Copia o texto do post no app e cola aqui.' } }];
}
if (text.length < 40) {
  return [{ json: { chatId, needsLlm: false, reply: 'Nao entendi. Para comentar um post, cola o texto inteiro dele. /menu mostra os comandos.' } }];
}
return [{ json: llm('comentario', P_COMENT + text) }];

const ctx = $('Roteador').first().json;
const resp = $input.first().json;
const chatId = ctx.chatId;

function limpa(s) {
  return String(s || '')
    .replace(/\s*[—–]\s*/g, ', ')
    .replace(/, ,/g, ',')
    .trim();
}

let raw = '';
try { raw = resp.choices[0].message.content || ''; } catch (e) { raw = ''; }
if (!raw) {
  const erro = resp.error ? (resp.error.message || JSON.stringify(resp.error)) : 'resposta vazia';
  return [{ json: { chatId, text: 'A IA nao respondeu: ' + erro } }];
}

let data;
try {
  data = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  return [{ json: { chatId, text: 'Resposta fora do formato, segue crua:\n\n' + limpa(raw).slice(0, 3800) } }];
}

const out = [];
if (ctx.kind === 'post') {
  const v1 = limpa(data.v1), v2 = limpa(data.v2);
  out.push({ json: { chatId, text: 'VERSAO 1 · Bastidores (' + v1.length + ' caracteres)\n\n' + v1 } });
  out.push({ json: { chatId, text: 'VERSAO 2 · Arquitetura (' + v2.length + ' caracteres)\n\n' + v2 } });
  if (data.imagem) out.push({ json: { chatId, text: 'Prompt de imagem (Meta AI):\n\n' + String(data.imagem).trim() } });
} else {
  if (data.aviso) out.push({ json: { chatId, text: 'Aviso: ' + limpa(data.aviso) } });
  out.push({ json: { chatId, text: 'COMENTARIO 1\n\n' + limpa(data.c1) } });
  out.push({ json: { chatId, text: 'COMENTARIO 2\n\n' + limpa(data.c2) } });
}
return out;
